), inserted as (
insert into public.legal_import_rows(batch_id,chapter_id,source_code,normalized_code,sequence_number,legal_text,max_score,mandatory_level,partial_allowed,source_page,source_excerpt_hash,row_status,reviewer_note)
select b.id,r.chapter_id,r.source_code,r.normalized_code,r.sequence_number,r.legal_text,r.max_score,r.mandatory_level,r.partial_allowed,r.source_page,r.source_excerpt_hash,'needs_revision','Đã xác nhận cấu trúc mã/điểm/trang; chưa nhập nguyên văn tiêu chí.' from rows r cross join target_batch b
on conflict(batch_id,normalized_code) do update set source_code=excluded.source_code,max_score=excluded.max_score,mandatory_level=excluded.mandatory_level,partial_allowed=excluded.partial_allowed,source_page=excluded.source_page,source_excerpt_hash=excluded.source_excerpt_hash,row_status='needs_revision',reviewer_note=excluded.reviewer_note
returning id)
update public.legal_import_batches set status='imported',notes='Đã nạp cấu trúc 169 dòng; nguyên văn tiêu chí vẫn chờ đối chiếu.' where id=(select id from target_batch);

commit;
